/* true60 (the whole-frame form rule addendum): the Peahat / Seahat whole form. The frame decides from
 * Link (the attack, the bounce off his shield), the tick30 collision hits and the BG / water checks, and its eases,
 * timers, RNG draws and morf play run once per 30 Hz frame; as hand-converted per-step eases (81 cLib sites: the water
 * follow, the propeller ramp, ...) they left the Peahat off A's frame (c6ca17n2; N-step spec with real cLib). So daPH_Execute
 * runs whole once per 30 Hz frame on the tick30 step at dt 1 from the frame-start state (d/t60_whole.h, t60objw form):
 * every decision with the other actors' current state, the colliders registered once for the tick30 collision Move
 * (one-sweep-per-frame attack), the move once. The earlier steps change no logic state; the picture: frame interpolation (the port blends the skeleton
 * between the frame ends; process-order read). Nothing else needs the Peahat's per-step position (Link's knockback and the Co push
 * read its tick30 colliders). The per-step helpers below are inert inside the whole run (dt 1). Never held. Negative
 * control: T60C_NEGCTRL runs the execute on every step at dt. */
struct ph_class;
namespace ph_t60w {
static inline const t60w::Ops<ph_class>& ops() { return t60objw::Logic<ph_class>::kOps; }
}  // namespace ph_t60w
#include "d/actor/d_a_enemy_anm_t60.h"

/* true60 (hand: r3+0x48C has one write that is A's frame end, the other steps
 * use an unstored view): the bob phase mBobPhase (+1000 per sea_water_check call while floating; daPH_Execute calls it
 * up to twice per frame; cleared by the water entry, which A finds after the add in the same frame). Per call ordinal j
 * of the step: the frame's first call j stores A's value after call j (its frame-start value + 1000; a later step may
 * skip sea_water_check under daPH_Execute's state hold, so the store cannot wait for the tick30 step); every call's
 * sine takes the view: call j's frame-start value + the frame's integer shares so far (the tick30 step: + 1000). A water
 * entry this frame (mark PH_T60_BOB_RESET at the clear) ends the frame at 0, as in A: no add after it this frame.
 * dt 1: the original add. Host: per actor (s_add sites 40-49, keyed by the actor). */
enum { PH_T60_BOB_RESET = 21, PH_T60_SWC_STEP = 40, PH_T60_SWC_ORD = 41, PH_T60_BOB_START = 42, PH_T60_BOB_ACC = 46,
       PH_T60_SWC_CUR = 50 };
static inline t60c::AddEntry& ph_t60_bob_entry(const void* k, int site) {
    return t60c::s_add.at(t60c::key(k, site) ^ 0x1000000000000000ull, t60c::frameTag());
}
/* at the top of sea_water_check: this call's ordinal within the step (0, 1, ...), kept for ph_t60_bob; dt 1: 0 */
static inline int ph_t60_swc_enter(const void* k) {
#ifndef T60C_NEGCTRL
    if (!t60c::on())
        return 0;
    const u32 tag = t60c::frameTag();
    const s32 sc = (s32)t60_step_counter();
    t60c::AddEntry& st = ph_t60_bob_entry(k, PH_T60_SWC_STEP);
    t60c::AddEntry& od = ph_t60_bob_entry(k, PH_T60_SWC_ORD);
    if (st.tag != tag || st.given != sc) {
        st.tag = tag;
        st.given = sc;
        od.tag = tag;
        od.given = 0;
    }
    const int j = od.given < 3 ? od.given : 3;
    od.given++;
    if (t60::first_step() && j == 0) {
        /* a new frame (or the harness's next input with the same frame word): no stale frame-start values */
        for (int jj = 0; jj < 4; jj++)
            ph_t60_bob_entry(k, PH_T60_BOB_START + jj).tag = tag - 1u;
    }
    t60c::AddEntry& cu = ph_t60_bob_entry(k, PH_T60_SWC_CUR);
    cu.tag = tag;
    cu.given = j;
    return j;
#else
    (void)k;
    return 0;
#endif
}
template <class P> static inline s16 ph_t60_bob(P* i, s16 t) {
#ifndef T60C_NEGCTRL
    if (t60c::on()) {
        if (t60c::marked(PH_T60_BOB_RESET, i))
            return t;
        const u32 tag = t60c::frameTag();
        t60c::AddEntry& cu = ph_t60_bob_entry(i, PH_T60_SWC_CUR);
        const int j = cu.tag == tag ? cu.given : 0; /* the enclosing sea_water_check call's ordinal in the step */
        t60c::AddEntry& es = ph_t60_bob_entry(i, PH_T60_BOB_START + j);
        t60c::AddEntry& ea = ph_t60_bob_entry(i, PH_T60_BOB_ACC + j);
        if (es.tag != tag) {
            es.tag = tag;
            es.given = t;
            ea.tag = tag;
            ea.given = 0;
            i->mBobPhase = (s16)(t + 1000);
        }
        ea.given += t60c::share(1000);
        if (t60::tick30())
            ea.given = 1000;
        return (s16)((s16)es.given + (s16)ea.given);
    }
#endif
    const s16 v = (s16)(t + 1000);
    i->mBobPhase = v;
    return v;
}
template <class P> static inline void ph_t60_bob_reset(P* i) { t60c::mark(PH_T60_BOB_RESET, i); }

/* true60 (the per-step movement rule,'s exact arc for inline gravity, as nz): the y offset dv x (1 - dt) / 2 for this step's gravity
 * change, ridden on posMove's y step as arc / dt (speed.y put back after the move); dt 1: none */
static inline f32 ph_t60_arc(f32 dv) {
#ifdef T60C_NEGCTRL
    (void)dv;
    return 0.0f;
#else
    if (!t60c::on())
        return 0.0f;
    return gabi::fmuls_ppc(gabi::fmuls_ppc(dv, gabi::fsubs_ppc(1.0f, t60::dt())), 0.5f);
#endif
}
static inline f32 ph_t60_arc_speed(f32 arc) { return t60c::on() ? arc / t60::dt() : 0.0f; }

/* true60 (hand): speed.y assigned on this step by a per-step assignment of the dispatch (ph_fujyou_rise:
 * speed.y = mRiseSpeed; case 0x24: 70): A's frame is v = X + gravity, pos += v; with X set again on every step the
 * frame's gravity is whole on every step (pos moves v x dt per step: X + gravity over the frame), no exact-arc term.
 * Per actor (s_add site 51: the step counter of the assignment). */
static inline void ph_t60_vy_set(const void* k) {
#ifndef T60C_NEGCTRL
    if (!t60c::on())
        return;
    t60c::AddEntry& e = ph_t60_bob_entry(k, 51);
    e.tag = t60c::frameTag();
    e.given = (s32)t60_step_counter();
#else
    (void)k;
#endif
}
static inline bool ph_t60_vy_assigned(const void* k) {
#ifndef T60C_NEGCTRL
    if (!t60c::on())
        return false;
    t60c::AddEntry& e = ph_t60_bob_entry(k, 51);
    return e.tag == t60c::frameTag() && e.given == (s32)t60_step_counter();
#else
    (void)k;
    return false;
#endif
}
/* true60 (hand): speed.y was assigned on an EARLIER step of this frame (with the frame's whole gravity
 * there) and not on this one (the state ended, e.g. by a hit): A's frame added its gravity once, so this step adds none */
static inline bool ph_t60_vy_assigned_earlier(const void* k) {
#ifndef T60C_NEGCTRL
    if (!t60c::on())
        return false;
    t60c::AddEntry& e = ph_t60_bob_entry(k, 51);
    return e.tag == t60c::frameTag() && e.given != (s32)t60_step_counter();
#else
    (void)k;
    return false;
#endif
}
/* the frame's first step: no assignment yet (the harness reuses frame words across inputs) */
static inline void ph_t60_vy_clear(const void* k) {
#ifndef T60C_NEGCTRL
    if (!t60c::on())
        return;
    ph_t60_bob_entry(k, 51).tag = t60c::frameTag() - 1u;
#else
    (void)k;
#endif
}
/* the frame-start value of a float (heldInt bits) */
static inline f32 ph_t60_held_f(f32 live, int site, const void* k) {
    s32 b;
    __builtin_memcpy(&b, &live, 4);
    b = t60c::heldInt(b, site, k);
    f32 v;
    __builtin_memcpy(&v, &b, 4);
    return v;
}

/* true60 (hand): the frame's first step counter (s_add site 52, set at daPH_Execute's top on the first step) and the
 * part of the frame after the current step ((N - k) / N for step k; 0 on the tick30 step and at dt 1) */
static inline void ph_t60_frame_begin(const void* k) {
#ifndef T60C_NEGCTRL
    if (!t60c::on() || !t60::first_step())
        return;
    t60c::AddEntry& e = ph_t60_bob_entry(k, 52);
    e.tag = t60c::frameTag();
    e.given = (s32)t60_step_counter();
#else
    (void)k;
#endif
}
static inline f32 ph_t60_rest(const void* k) {
#ifndef T60C_NEGCTRL
    if (!t60c::on() || t60::tick30())
        return 0.0f;
    t60c::AddEntry& e = ph_t60_bob_entry(k, 52);
    if (e.tag != t60c::frameTag())
        return 0.0f;
    const s32 kk = (s32)t60_step_counter() - e.given + 1;
    const s32 n = (s32)t60::steps();
    return kk >= n ? 0.0f : (f32)(n - kk) / (f32)n;
#else
    (void)k;
    return 0.0f;
#endif
}

/* true60 (hand): an init case that falls through (mark 23 at its first-step mMode++) runs the next
 * case's body in the same frame in A; the one-state-step hold lets the frame's later steps run that state too (its
 * per-step shares complete A's frame; the init itself does not run again). The post-init state per actor and frame
 * (s_add site 53). */
static inline void ph_t60_post_init_set(const void* k, s32 state) {
#ifndef T60C_NEGCTRL
    if (!t60c::on())
        return;
    t60c::AddEntry& e = ph_t60_bob_entry(k, 53);
    e.tag = t60c::frameTag();
    e.given = state;
#else
    (void)k, (void)state;
#endif
}
/* the frame's first step: no post-init state yet (the harness reuses frame words across inputs) */
static inline void ph_t60_post_init_clear(const void* k) {
#ifndef T60C_NEGCTRL
    if (!t60c::on())
        return;
    ph_t60_bob_entry(k, 53).tag = t60c::frameTag() - 1u;
#else
    (void)k;
#endif
}
static inline bool ph_t60_post_init_is(const void* k, s32 state) {
#ifndef T60C_NEGCTRL
    if (!t60c::on())
        return false;
    t60c::AddEntry& e = ph_t60_bob_entry(k, 53);
    return e.tag == t60c::frameTag() && e.given == state;
#else
    (void)k, (void)state;
    return false;
#endif
}

/* true60 (hand): the water entry's step (s_add site 54): a leave found on a LATER step of the frame
 * whose earlier step entered the water waits (A's frame has one water state edge per check order; the leave is A's next
 * frame's, which the next frame's checks find again); a leave on the entry's own step stays (A's frame order) */
static inline void ph_t60_water_entry_note(const void* k) {
#ifndef T60C_NEGCTRL
    if (!t60c::on())
        return;
    t60c::AddEntry& e = ph_t60_bob_entry(k, 54);
    e.tag = t60c::frameTag();
    e.given = (s32)t60_step_counter();
#else
    (void)k;
#endif
}
/* the frame's first sea_water_check call: no entry yet this frame (the harness reuses frame words across inputs) */
static inline void ph_t60_water_entry_clear(const void* k) {
#ifndef T60C_NEGCTRL
    if (!t60c::on())
        return;
    ph_t60_bob_entry(k, 54).tag = t60c::frameTag() - 1u;
#else
    (void)k;
#endif
}
static inline bool ph_t60_leave_held(const void* k) {
#ifndef T60C_NEGCTRL
    if (!t60c::on())
        return false;
    t60c::AddEntry& e = ph_t60_bob_entry(k, 54);
    return e.tag == t60c::frameTag() && e.given != (s32)t60_step_counter();
#else
    (void)k;
    return false;
#endif
}

/* true60 (hand, ph (d) 0x45B, first-step AI-timer order beats placement): speedF as it was
 * before the frame's first sea_water_check zeroed it (s_add site 55). A reads speedF in the Seahat bounce-end test
 * (ph_hane_move 0xB) BEFORE its frame's water check writes 0; a later step's test reads that frame-start-order value, so
 * the bounce ends on A's frame (the next one), not one step early. Cleared on the frame's first step / first check. */
static inline void ph_t60_speedf_zero_note(const void* k, f32 before) {
#ifndef T60C_NEGCTRL
    if (!t60c::on() || t60::tick30())
        return;
    t60c::AddEntry& e = ph_t60_bob_entry(k, 55);
    if (e.tag == t60c::frameTag())
        return; /* the frame's first write only */
    e.tag = t60c::frameTag();
    __builtin_memcpy(&e.given, &before, 4);
#else
    (void)k, (void)before;
#endif
}
static inline void ph_t60_speedf_zero_clear(const void* k) {
#ifndef T60C_NEGCTRL
    if (!t60c::on())
        return;
    ph_t60_bob_entry(k, 55).tag = t60c::frameTag() - 1u;
#else
    (void)k;
#endif
}
static inline f32 ph_t60_speedf_test(const void* k, f32 live) {
#ifndef T60C_NEGCTRL
    if (!t60c::on())
        return live;
    t60c::AddEntry& e = ph_t60_bob_entry(k, 55);
    if (e.tag != t60c::frameTag())
        return live;
    f32 v;
    __builtin_memcpy(&v, &e.given, 4);
    return v;
#else
    (void)k;
    return live;
#endif
}

/* true60 (hand, ph (a)): the float targets as the state's formula last stored
 * them this frame and the phases it used (s_add sites 56-58: x, y, z target bits; 59-61: the x, y, z phases).
 * ph_t60_state_rest continues from those phases on the held steps: a target that still holds the stored value is
 * recomputed from the stored phase + the step's share (A computes it from the frame's whole add, whatever the frame's
 * later code does to the live phase, e.g. ph_zero_wobble); a target the frame's later code wrote (the water check's 0)
 * stays; the live phase gets the share only where it still holds the stored phase. Compared by bits. */
static inline void ph_t60_target_note(const void* k, f32 x, f32 y, f32 z, s16 px, s16 py, s16 pz) {
#ifndef T60C_NEGCTRL
    if (!t60c::on())
        return;
    const f32 v[3] = {x, y, z};
    const s16 p[3] = {px, py, pz};
    for (int i = 0; i < 3; i++) {
        t60c::AddEntry& e = ph_t60_bob_entry(k, 56 + i);
        e.tag = t60c::frameTag();
        __builtin_memcpy(&e.given, &v[i], 4);
        t60c::AddEntry& f = ph_t60_bob_entry(k, 59 + i);
        f.tag = t60c::frameTag();
        f.given = p[i];
    }
#else
    (void)k, (void)x, (void)y, (void)z, (void)px, (void)py, (void)pz;
#endif
}
/* the rest's continuation on a held step: the axis's phase (and, when recomputed, its target bits) move on */
static inline void ph_t60_target_note_axis(const void* k, int axis, bool target, f32 v, s16 phase) {
#ifndef T60C_NEGCTRL
    if (!t60c::on())
        return;
    if (target) {
        t60c::AddEntry& e = ph_t60_bob_entry(k, 56 + axis);
        e.tag = t60c::frameTag();
        __builtin_memcpy(&e.given, &v, 4);
    }
    t60c::AddEntry& f = ph_t60_bob_entry(k, 59 + axis);
    f.tag = t60c::frameTag();
    f.given = phase;
#else
    (void)k, (void)axis, (void)target, (void)v, (void)phase;
#endif
}
/* the stored target bits and phase of an axis (false: the formula did not store this frame) */
static inline bool ph_t60_target_noted(const void* k, int axis, s32* bits, s16* phase) {
#ifndef T60C_NEGCTRL
    if (!t60c::on())
        return false;
    t60c::AddEntry& e = ph_t60_bob_entry(k, 56 + axis);
    t60c::AddEntry& f = ph_t60_bob_entry(k, 59 + axis);
    if (e.tag != t60c::frameTag() || f.tag != t60c::frameTag())
        return false;
    *bits = e.given;
    *phase = (s16)f.given;
    return true;
#else
    (void)k, (void)axis, (void)bits, (void)phase;
    return false;
#endif
}

/* true60 (hand): sea_water_check's answer. Every call of A's frame runs
 * before daPH_Execute's fopAcM_posMove, at the frame-start position, so the frame's answers are the first step's: a later
 * step's call k answers with the first step's call k (s_add sites 70-73, by the call ordinal; 74: the first step's call
 * count). A later step that makes more calls than the first answers live (ph_t60_swc_fallbacks counts them; N-step spec counts
 * them with a debug copy). Without it a later step tested the position after an earlier step's motion (N-step spec gen seed
 * 7006284: step 2's answer in-water, the rise's speed.y 70 -> 0 where A's frame keeps 70). */
static unsigned ph_t60_swc_fallbacks;
static inline int ph_t60_swc_ret(const void* k, int ord, int live) {
#ifndef T60C_NEGCTRL
    if (!t60c::on())
        return live;
    const u32 tag = t60c::frameTag();
    t60c::AddEntry& e = ph_t60_bob_entry(k, 70 + ord);
    t60c::AddEntry& n = ph_t60_bob_entry(k, 74);
    if (t60::first_step()) {
        e.tag = tag;
        e.given = live;
        if (ord == 0 || n.tag != tag) {
            n.tag = tag;
            n.given = 0;
        }
        if (n.given < ord + 1)
            n.given = ord + 1;
        return live;
    }
    if (n.tag == tag && ord < n.given && e.tag == tag)
        return e.given;
    ph_t60_swc_fallbacks++;
    return live;
#else
    (void)k, (void)ord;
    return live;
#endif
}
/* true60 (hand, ph (a)): a phase / angle the state added to this frame, as it
 * stood after the add (s_add sites 62 roll phase, 63 pitch phase, 64 shape_angle.y). ph_t60_state_rest adds the rest
 * of the frame only where the value still holds that (a later write of the frame, e.g. ph_zero_wobble or a new state's
 * init, stays as in A). Sites 56-64 start clear on the frame's first step (frame words reused across harness inputs). */
static inline void ph_t60_val_note(const void* k, int site, s32 v) {
#ifndef T60C_NEGCTRL
    if (!t60c::on())
        return;
    t60c::AddEntry& e = ph_t60_bob_entry(k, site);
    e.tag = t60c::frameTag();
    e.given = v;
#else
    (void)k, (void)site, (void)v;
#endif
}
static inline bool ph_t60_val_kept(const void* k, int site, s32 live) {
#ifndef T60C_NEGCTRL
    if (!t60c::on())
        return true;
    t60c::AddEntry& e = ph_t60_bob_entry(k, site);
    return e.tag != t60c::frameTag() || e.given == live;
#else
    (void)k, (void)site, (void)live;
    return true;
#endif
}
static inline void ph_t60_notes_clear(const void* k) {
#ifndef T60C_NEGCTRL
    if (!t60c::on())
        return;
    for (int site = 56; site <= 64; site++)
        ph_t60_bob_entry(k, site).tag = t60c::frameTag() - 1u;
#else
    (void)k;
#endif
}
/* the state's add with its note (s16 field) */
template <class F> static inline void ph_t60_add_note(const void* k, int site, F* f, s16 add) {
    *f = (s16)((s16)*f + add);
    ph_t60_val_note(k, site, (s16)*f);
}
/* the rest's add where the value still holds the note */
template <class F> static inline void ph_t60_add_kept(const void* k, int site, F* f, s16 add) {
    if (ph_t60_val_kept(k, site, (s16)*f))
        ph_t60_add_note(k, site, f, add);
}

/* true60 (hand): the share that completes the frame's per-frame add on the step a state ends (the later steps of the
 * frame do not run it): perFrame - the earlier steps' parts, as share() gives on the tick30 step */
static inline s32 ph_t60_share_rest(const void* k, s32 perFrame) {
#ifndef T60C_NEGCTRL
    if (!t60c::on() || t60::tick30())
        return t60c::share(perFrame);
    t60c::AddEntry& e = ph_t60_bob_entry(k, 52);
    if (e.tag != t60c::frameTag())
        return t60c::share(perFrame);
    const s32 kk = (s32)t60_step_counter() - e.given + 1;
    const s32 part = (s32)((f32)perFrame * t60::dt());
    return perFrame - part * (kk - 1);
#else
    (void)k;
    return perFrame;
#endif
}
